<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
const projects=ref<any[]>([]),p=ref<any>(null),tab=ref('需求'),busy=ref(false),error=ref(''),notice=ref(''),name=ref('')
const body=ref(''),docName=ref('需求说明'),role=ref('requirement'),previous=ref(''),docs=ref<string[]>([]),reqs=ref<string[]>([]),cases=ref<string[]>([]),consent=ref(false)
const drafts=ref<Record<string,{text:string,answer:string}>>({}),editor=ref<any>(null),steps=ref(''),review=ref(''),batchNote=ref(''),filter=ref('all'),source=ref<any>(null),changes=ref<Record<string,string[]>>({})
const settings=ref<any>(null),settingsInfo=ref<any>(null),settingsVisible=ref(false),tasks=ref<any[]>([]),progress=ref(''),trace=ref<any[]>([])
const runName=ref('本次测试'),runCase=ref(''),runStatus=ref('未执行'),runNote=ref('')
const s=computed(()=>p.value?.state),active=computed(()=>tasks.value.find(t=>['queued','running'].includes(t.status)))
const shown=computed(()=>s.value?.cases.filter((c:any)=>filter.value==='all'||(filter.value==='applied'?!!c.applied_to:c.status===filter.value&&!c.applied_to))??[])
const pending=computed(()=>s.value?.changes.filter((c:any)=>c.status==='pending')??[])
let timer:ReturnType<typeof setTimeout>|undefined,stream:EventSource|null=null,disposed=false
const status=(v:string)=>({draft:'待审核',confirmed:'已确认',excluded:'已排除',approved:'已审核',rejected:'已驳回',needs_review:'待复审',queued:'等待处理',running:'处理中',completed:'已完成',failed:'未完成',blocked:'已停止',accepted:'已接受'} as Record<string,string>)[v]??v
const kind=(v:string)=>({unchanged:'内容未变，确认来源',added:'新增需求',possible_change:'可能修改或拆分合并',possibly_removed:'可能删除或被合并'} as Record<string,string>)[v]??v
const date=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false})
const path=()=>'/projects/'+p.value.id
async function api(url:string,value?:unknown){const response=await fetch('/api/v1/caseflow'+url,value===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});const result=await response.json();if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'输入未通过检查');return result}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
function use(value:any){if(p.value?.id===value.id&&p.value.revision>value.revision)return;p.value=value;cases.value=cases.value.filter(id=>value.state.cases.some((c:any)=>c.id===id&&!c.applied_to));for(const r of value.state.requirements)if(!drafts.value[r.id])drafts.value[r.id]={text:r.text,answer:''};docs.value=docs.value.filter(id=>value.state.documents.some((d:any)=>d.id===id));if(!docs.value.length)docs.value=value.state.documents.map((d:any)=>d.id);reqs.value=reqs.value.filter(id=>value.state.requirements.some((r:any)=>r.id===id&&r.status==='confirmed'));for(const c of value.state.changes)if(!changes.value[c.id])changes.value[c.id]=c.old_ids.slice(0,1)}
async function refresh(){const id=p.value?.id;if(!id)return;const value=await api('/projects/'+id);if(p.value?.id===id)use(value)}
async function list(){projects.value=await api('/projects')}
function reset(){stream?.close();if(timer)clearTimeout(timer);drafts.value={};docs.value=[];reqs.value=[];cases.value=[];trace.value=[];tasks.value=[];tab.value='需求';consent.value=false;progress.value='';editor.value=null;source.value=null;previous.value='';runCase.value=''}
async function open(id:string){await act(async()=>{reset();use(await api('/projects/'+id));localStorage.setItem('caseflow-project',id);await loadTasks()})}
async function home(){await act(async()=>{reset();p.value=null;localStorage.removeItem('caseflow-project');await list()})}
async function create(){await act(async()=>{reset();use(await api('/projects',{name:name.value}));name.value='';localStorage.setItem('caseflow-project',p.value.id);await list()})}
async function example(key:string){await act(async()=>{reset();use(await api('/examples/'+key,{}));localStorage.setItem('caseflow-project',p.value.id);await list()})}
async function saveText(){await act(async()=>{use(await api(path()+'/texts',{revision:p.value.revision,name:docName.value,content:body.value,role:role.value,previous_id:previous.value||null}));body.value='';previous.value='';consent.value=false;notice.value='资料已保存，请检查原文并选择处理范围。'})}
async function upload(e:Event,result=false){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await act(async()=>{const form=new FormData();form.append('file',file);form.append('revision',p.value.revision);if(result){form.append('name',runName.value);form.append('request_id',crypto.randomUUID())}else{form.append('role',role.value);if(previous.value)form.append('previous_id',previous.value)}const response=await fetch('/api/v1/caseflow'+path()+(result?'/runs/import':'/files'),{method:'POST',body:form});const value=await response.json();if(!response.ok)throw new Error(value.detail);use(value);previous.value='';consent.value=false;notice.value=result?'执行结果已导入。':'资料已导入，请核对解析内容。'});input.value=''}
function original(d:any,page?:number){source.value={title:d.name+(page?' · 第'+page+'页':''),text:(page?[d.pages[page-1]]:d.pages).map((t:string,i:number)=>'【第'+(page??i+1)+'页】\n'+t).join('\n\n')}}
function citation(q:any){const d=s.value.documents.find((d:any)=>d.id===q.document_id);if(d)original(d,q.page)}
async function saveReq(r:any,state:string){await act(async()=>{const d=drafts.value[r.id]!;use(await api(path()+'/requirements/'+r.id,{revision:p.value.revision,text:d.text,status:state,answer:d.answer}));drafts.value[r.id]={text:s.value.requirements.find((v:any)=>v.id===r.id).text,answer:''};notice.value='需求已保存。'})}
async function start(type:string){await act(async()=>{if(!consent.value)throw new Error('请先确认本轮资料范围');const selected=type==='extract'?docs.value.filter(id=>s.value.documents.find((d:any)=>d.id===id)?.role==='requirement'):docs.value;if(!selected.length)throw new Error('请选择本轮处理资料');const key='caseflow-pending:'+p.value.id;if(localStorage.getItem(key)){await loadTasks();if(localStorage.getItem(key))throw new Error('上次提交结果尚未找回，请刷新查看处理记录，避免重复生成。')};const request_id=crypto.randomUUID();localStorage.setItem(key,request_id);try{const task=await api(path()+'/tasks',{revision:p.value.revision,request_id,kind:type,document_ids:selected,requirement_ids:type==='generate'?reqs.value:[],consent:true});localStorage.removeItem(key);tasks.value.unshift(task);follow(task)}catch(e){await loadTasks();throw e}})}
async function resumeTask(t:any){await act(async()=>{const result=await api('/tasks/'+t.id+'/resume',{revision:p.value.revision});await loadTasks();follow(result)})}
async function loadTasks(){const id=p.value?.id;if(!id)return;const result=await api('/projects/'+id+'/tasks');if(p.value?.id!==id)return;tasks.value=result;const key='caseflow-pending:'+id;if(tasks.value.some(t=>t.request_id===localStorage.getItem(key)))localStorage.removeItem(key);if(active.value)follow(active.value)}
function follow(t:any){stream?.close();if(timer)clearTimeout(timer);stream=new EventSource('/api/v1/caseflow/tasks/'+t.id+'/events?after='+(localStorage.getItem('cf-cursor:'+t.id)??'0'));stream.onmessage=e=>{if(/^\d+$/.test(e.lastEventId))localStorage.setItem('cf-cursor:'+t.id,e.lastEventId);try{const item=JSON.parse(e.data);progress.value=item.payload?.message??'';if(item.kind==='tool')trace.value.push(item.payload)}catch{}};stream.onerror=()=>progress.value='正在重新连接，已保存任务仍可查询';void poll()}
async function poll(){const id=p.value?.id;if(disposed||!id)return;try{const result=await api('/projects/'+id+'/tasks');if(disposed||p.value?.id!==id)return;tasks.value=result;if(active.value)timer=setTimeout(poll,1500);else{stream?.close();await refresh();if(disposed||p.value?.id!==id)return;if(tasks.value[0]?.error)error.value=tasks.value[0].error;else notice.value='处理完成，请审核结果。';progress.value=''}}catch{if(!disposed&&p.value?.id===id)timer=setTimeout(poll,2500)}}
function edit(c:any){editor.value=JSON.parse(JSON.stringify(c));steps.value=c.steps.join('\n');review.value=c.review_note??''}
async function saveCase(state:string){await act(async()=>{const c=editor.value;use(await api(path()+'/cases/'+c.id,{revision:p.value.revision,title:c.title,preconditions:c.preconditions,data:c.data,steps:steps.value.split('\n').filter(t=>t.trim()),expected:c.expected,status:state,review_note:review.value}));editor.value=null;notice.value='用例已保存。'})}
async function applyProposal(){await act(async()=>{const c=editor.value;use(await api(path()+'/cases/'+c.id,{revision:p.value.revision,title:c.title,preconditions:c.preconditions,data:c.data,steps:steps.value.split('\n').filter(t=>t.trim()),expected:c.expected,status:'draft',review_note:review.value}));use(await api(path()+'/proposals/'+c.id,{revision:p.value.revision}));editor.value=null;notice.value='建议已应用到原用例并保存为草稿，请审核。'})}
async function batch(state:string){await act(async()=>{use(await api(path()+'/reviews',{revision:p.value.revision,ids:cases.value,status:state,review_note:batchNote.value}));cases.value=[];batchNote.value='';notice.value='审核结果已保存。'})}
async function decide(c:any,action:string){await act(async()=>{use(await api(path()+'/changes/'+c.id,{revision:p.value.revision,action,target_ids:['add','reject'].includes(action)?[]:changes.value[c.id]??[]}));notice.value='变更决定已保存，请检查需求和受影响用例。'})}
async function strategy(e:Event){await act(async()=>{use(await api(path()+'/strategy',{revision:p.value.revision,mode:(e.target as HTMLSelectElement).value}));consent.value=false})}
async function showSettings(){settingsVisible.value=true;await act(async()=>{settingsInfo.value=await api('/settings');settings.value=JSON.parse(JSON.stringify(settingsInfo.value.settings))})}
async function saveSettings(){await act(async()=>{settingsInfo.value=await api('/settings',settings.value);notice.value='设置已保存。';consent.value=false})}
async function record(){await act(async()=>{const c=s.value.cases.find((c:any)=>c.id===runCase.value);if(!c)throw new Error('请选择已审核用例');use(await api(path()+'/runs',{revision:p.value.revision,request_id:crypto.randomUUID(),name:runName.value,results:[{case_id:c.id,revision:c.revision,status:runStatus.value,note:runNote.value}]}));runNote.value='';notice.value='实际执行结果已记录。'})}
function escape(e:KeyboardEvent){if(e.key==='Escape'){if(source.value)source.value=null;else if(editor.value)editor.value=null;else settingsVisible.value=false}if(e.key==='Tab'&&(source.value||editor.value||settingsVisible.value)){const dialogs=Array.from(document.querySelectorAll('.cf .dialog'));const dialog=source.value?document.querySelector('.cf .source-overlay .dialog'):dialogs[dialogs.length-1];const targets=Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select,textarea,summary,a[href]')??[]);const first=targets[0],last=targets[targets.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
let previousFocus:HTMLElement|null=null
watch(()=>!!(source.value||editor.value||settingsVisible.value),async opened=>{if(opened){previousFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.cf .dialog button')?.focus()}else previousFocus?.focus()})
onMounted(async()=>{window.addEventListener('keydown',escape);await act(async()=>{await list();const id=localStorage.getItem('caseflow-project');if(id&&projects.value.some(x=>x.id===id)){reset();use(await api('/projects/'+id));await loadTasks()}})})
onUnmounted(()=>{disposed=true;stream?.close();if(timer)clearTimeout(timer);window.removeEventListener('keydown',escape)})
</script>
<template>
<div class="cf"><aside><button class="brand" @click="home" :disabled="busy"><b>C</b><span>CaseFlow<small>需求与测试用例工作台</small></span></button><button class="home" @click="home" :disabled="busy">▦　我的项目</button><template v-if="p"><p class="project-name">{{p.name}}</p><nav aria-label="项目导航"><button v-for="t in ['需求','用例','变更']" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}<small v-if="t==='变更'&&pending.length">{{pending.length}}</small></button></nav></template><div class="aside-bottom"><button @click="showSettings">⚙　设置</button><small>资料有依据，变更可跟踪</small></div></aside>
<main><header><span>{{p?p.name:'我的项目'}} <span class="muted" v-if="p"> / {{tab}}</span></span><small class="local">● 本机工作台</small></header><div class="content"><p v-if="error" class="message error" role="alert">{{error}} <button @click="error=''" aria-label="关闭错误">×</button></p><p v-if="notice" class="message success" role="status">{{notice}}</p>
<template v-if="!p"><div class="title"><div><small class="eyebrow">CASEFLOW WORKSPACE</small><h1>从需求到可交付的测试用例</h1><p>整理需求、核对依据，让每一次修改都有记录。</p></div></div><form class="card create" @submit.prevent="create"><div><h2>开始一个项目</h2><p class="muted">为需求说明、参考资料和测试用例建立共同的工作空间。</p></div><div class="inline"><input v-model="name" aria-label="项目名称" placeholder="项目名称，例如会议室预约系统" maxlength="100" required><button class="primary" :disabled="busy||!name.trim()">新建项目</button></div></form><div class="heading"><h2>最近项目</h2><small>{{projects.length}} 个项目</small></div><div class="project-grid"><button class="card project" v-for="x in projects" :key="x.id" @click="open(x.id)"><span class="folder">▤</span><h3>{{x.name}}</h3><p>{{x.summary.confirmed}} 条已确认需求 · {{x.summary.approved}} 条已审核用例</p><small>更新于 {{date(x.updated_at)}}</small><span class="arrow">↗</span></button></div><p v-if="!projects.length" class="card empty">还没有项目。创建一个项目，或用下方示例了解流程。</p><div class="heading"><h2>用示例试一试</h2><small>示例资料，不是真实业务记录</small></div><div class="examples"><button @click="example('reservation')" :disabled="busy">会议室预约<small>时段、权限与取消规则 →</small></button><button @click="example('permission')" :disabled="busy">文件共享<small>访问权限与授权变更 →</small></button><button @click="example('registration')" :disabled="busy">活动报名<small>名额、重复报名与截止时间 →</small></button></div></template>
<template v-else-if="s"><p v-if="s.example" class="message">这是预置示例，包含人工编写的需求和用例，非模型生成结果。可先确认需求，体验审核与导出；真实资料请新建项目。</p><div class="title"><div><h1>{{tab==='需求'?'先把需求说明白':tab==='用例'?'让每条用例可核对':'把变化带到用例里'}}</h1><p>{{tab==='需求'?'导入现有资料，确认规则，再开始设计测试。':tab==='用例'?'审核后交付用例，实际执行结果单独记录。':'逐项核对修改建议，保留已经确认的工作。'}}</p></div><button class="secondary" @click="act(refresh)" :disabled="busy">刷新</button></div><p v-if="active" class="progress" role="status">◌ {{progress||'正在处理所选资料，离开页面后仍可查询。'}}</p>
<template v-if="tab==='需求'"><section class="card"><div class="heading"><h2>添加资料</h2><small>支持 Word、文本 PDF、Markdown 和 TXT</small></div><div class="inline wrap"><label>资料用途<select v-model="role"><option value="requirement">需求说明</option><option value="context">补充参考</option></select></label><label>资料名称<input v-model="docName"></label><label>更新已有资料<select v-model="previous"><option value="">作为新资料添加</option><option v-for="d in s.documents.filter((d:any)=>d.role===role)" :key="d.id" :value="d.id">{{d.name}}</option></select></label></div><label for="cf-text">直接粘贴需求</label><textarea id="cf-text" v-model="body" rows="4" placeholder="描述业务规则、操作条件和期望结果。暂时不清楚的规则也可以先记录。"></textarea><div class="actions"><button class="primary" @click="saveText" :disabled="busy||!!active||!body.trim()">保存文字</button><label class="upload secondary">上传文件<input type="file" accept=".md,.txt,.pdf,.docx" @change="upload($event)" :disabled="busy||!!active"></label><small class="muted">每份最多 5 MiB；上传后请核对解析内容。</small></div></section>
<section class="card" v-if="s.documents.length"><div class="heading"><h2>本轮资料</h2><small>{{docs.length}} 份已选择</small></div><div class="document" v-for="d in s.documents" :key="d.id"><label class="check"><input type="checkbox" v-model="docs" :value="d.id" @change="consent=false"><span><strong>{{d.name}}</strong><small>{{d.role==='requirement'?'需求说明':'补充参考'}} · {{d.pages.length}} 页 · {{date(d.created_at)}}<span v-if="d.previous_id"> · 更新资料</span></small></span></label><button class="text-button" @click="original(d)">查看原文</button></div><label class="check consent"><input type="checkbox" v-model="consent">允许本轮处理所选资料；系统可在这些资料内检索，并向所配置模型发送片段。</label><div class="actions"><button class="primary" @click="start('extract')" :disabled="busy||!!active||!consent">整理需求</button><details><summary>资料检索选项</summary><label>选取方式<select :value="s.retrieval_mode??'keyword'" @change="strategy"><option value="keyword">关键词</option><option value="vector">语义检索</option><option value="hybrid">关键词与语义</option><option value="rerank">混合检索并排序</option></select></label><button class="secondary" @click="start('index')" :disabled="busy||!!active||!consent">建立资料索引</button><p class="muted">语义检索和排序需要有效模型额度，不会自动降级。</p></details></div></section>
<section class="card"><div class="heading"><h2>需求清单</h2><small>{{s.summary.confirmed}} 条已确认</small></div><p v-if="!s.requirements.length" class="empty">添加资料并整理后，在这里核对每条需求。</p><article class="requirement" v-for="r in s.requirements" :key="r.id"><div class="item-title"><label class="check"><input type="checkbox" v-model="reqs" :value="r.id" :disabled="r.status!=='confirmed'"><strong>{{r.code}}</strong></label><span class="badge" :class="r.status">{{r.status==='draft'?'待确认':status(r.status)}}</span><small class="muted">{{r.origin==='explicit'?'原文明示':'用户确认补充'}}</small></div><textarea :aria-label="r.code+'需求内容'" v-model="drafts[r.id]!.text" rows="2"></textarea><div class="citations"><button v-for="(q,i) in r.citations" :key="String(i)" @click="citation(q)">查看依据 · 第{{q.page}}页</button></div><div class="questions" v-if="r.questions.length"><strong>需要澄清</strong><p v-for="q in r.questions" :key="q">{{q}}</p><input v-model="drafts[r.id]!.answer" :aria-label="r.code+'澄清回答'" placeholder="填写已确定的规则；未知时可以暂不回答"></div><details v-if="r.answers.length"><summary>已确认的补充</summary><p v-for="(a,i) in r.answers" :key="String(i)">{{a.text}}</p></details><div class="actions"><button class="primary" @click="saveReq(r,'confirmed')" :disabled="busy||!!active">确认需求</button><button class="secondary" @click="saveReq(r,'draft')" :disabled="busy||!!active">保存草稿</button><button class="text-button" @click="saveReq(r,'excluded')" :disabled="busy||!!active">排除</button></div></article><div class="actions bottom" v-if="s.requirements.length"><span>{{reqs.length}} 条需求已选择</span><button class="primary" @click="start('generate')" :disabled="busy||!!active||!reqs.length||!consent">生成用例</button><small class="muted" v-if="!consent">请先确认上方本轮资料范围。</small></div></section></template>
<template v-if="tab==='用例'"><div class="metrics"><div><strong>{{s.summary.confirmed}}</strong><small>已确认需求</small></div><div><strong>{{s.summary.linked}} / {{s.summary.confirmed}}</strong><small>已有有效关联的需求</small></div><div><strong>{{s.summary.approved}}</strong><small>已审核用例</small></div><div><strong>{{s.summary.review}}</strong><small>待复审用例</small></div></div><section class="card"><div class="toolbar"><select v-model="filter" aria-label="筛选审核状态"><option value="all">全部用例</option><option value="draft">待审核</option><option value="approved">已审核</option><option value="needs_review">待复审</option><option value="rejected">已驳回</option><option value="applied">已应用建议</option></select><div class="actions"><a class="secondary" :href="'/api/v1/caseflow'+path()+'/export?format=xlsx'">导出 Excel</a><a class="secondary" :href="'/api/v1/caseflow'+path()+'/export?format=md'">导出 Markdown</a></div></div><p v-if="!shown.length" class="empty">还没有符合条件的用例。先在需求页确认规则并选择生成。</p><div v-else class="table-wrap"><table><thead><tr><th></th><th>用例</th><th>关联需求</th><th>类型</th><th>审核状态</th><th></th></tr></thead><tbody><tr v-for="c in shown" :key="c.id"><td><input type="checkbox" v-model="cases" :value="c.id" :disabled="!!c.applied_to" :aria-label="'选择'+c.code"></td><td><small>{{c.code}}</small><strong>{{c.title}}</strong><small v-if="c.replaces_case_id">修改建议 · 对应 {{s.cases.find((x:any)=>x.id===c.replaces_case_id)?.code}}</small><small v-if="c.basis==='suggestion'">补充建议 · 预期需确认</small></td><td>{{c.requirement_ids.map((id:string)=>s.requirements.find((r:any)=>r.id===id)?.code).join('、')}}</td><td>{{c.category}}</td><td><span class="badge" :class="c.status">{{c.applied_to?'已应用':status(c.status)}}</span></td><td><button class="text-button" @click="edit(c.applied_to?s.cases.find((x:any)=>x.id===c.applied_to):c)">{{c.applied_to?'查看原用例':'查看与编辑'}}</button></td></tr></tbody></table></div><div v-if="cases.length" class="review-bar"><span>已选 {{cases.length}} 条</span><input v-model="batchNote" placeholder="审核说明，例如已核对规则与预期结果" aria-label="批量审核说明"><button class="primary" @click="batch('approved')" :disabled="busy">审核通过</button><button class="secondary" @click="batch('rejected')" :disabled="busy">驳回</button></div><details class="detail"><summary>需求关联情况</summary><p class="muted">有关联不代表测试充分，也不代表已经执行。</p><p v-for="r in s.requirements.filter((r:any)=>r.status==='confirmed')" :key="r.id">{{r.code}} · {{r.text}} <span class="badge">{{s.summary.unlinked.includes(r.id)?'尚无有效关联':'已关联'}}</span></p></details></section><details class="card detail"><summary>执行结果</summary><p class="muted">记录实际执行的结果。旧修订结果保留，不自动算作当前用例通过。</p><div class="inline wrap"><label>测试批次<input v-model="runName"></label><label>用例<select v-model="runCase"><option value="">选择已审核用例</option><option v-for="c in s.cases.filter((c:any)=>c.status==='approved')" :key="c.id" :value="c.id">{{c.code}} {{c.title}}</option></select></label><label>结果<select v-model="runStatus"><option>通过</option><option>失败</option><option>阻塞</option><option>未执行</option></select></label></div><label>执行备注<input v-model="runNote" placeholder="填写实际现象或证据位置"></label><div class="actions"><button class="primary" @click="record" :disabled="busy||!runCase">记录结果</button><a class="secondary" :href="'/api/v1/caseflow'+path()+'/result-template'">下载导入模板</a><label class="upload secondary">导入结果<input type="file" accept=".xlsx,.csv" @change="upload($event,true)" :disabled="busy"></label></div><article class="run" v-for="r in [...s.runs].reverse()" :key="r.id"><strong>{{r.name}}</strong><small>{{date(r.created_at)}}</small><p v-for="(v,i) in r.results" :key="String(i)">{{v.code}} · 修订 {{v.revision}} · {{v.status}} <span class="muted">{{v.current?'当前审核修订':'历史结果'}} · {{v.note}}</span></p></article></details></template>
<template v-if="tab==='变更'"><section class="card"><div class="heading"><h2>待确认变更</h2><small>{{pending.length}} 项</small></div><p v-if="!pending.length" class="empty">没有待处理变更。在需求页选择“更新已有资料”，上传并整理更新内容。</p><article class="change" v-for="c in pending" :key="c.id"><div class="item-title"><span class="badge">{{kind(c.kind)}}</span><small>{{s.documents.find((d:any)=>d.id===c.document_id)?.name}}</small></div><div class="compare"><div><small>可能关联的原需求</small><label class="check" v-for="id in c.old_ids" :key="id"><input type="checkbox" v-model="changes[c.id]" :value="id"><span>{{s.requirements.find((r:any)=>r.id===id)?.code}} · {{s.requirements.find((r:any)=>r.id===id)?.text}}</span></label><p v-if="!c.old_ids.length" class="muted">未找到明确关联</p></div><div><small>新资料内容</small><p>{{c.proposed?.text??'未找到对应内容，请确认是否删除、拆分或合并。'}}</p></div></div><div class="actions"><button v-if="c.proposed" class="primary" @click="decide(c,'replace')" :disabled="busy||changes[c.id]?.length!==1">更新所选原需求</button><button v-if="c.proposed" class="secondary" @click="decide(c,'add')" :disabled="busy">作为新增需求</button><button v-if="!c.proposed" class="secondary" @click="decide(c,'remove')" :disabled="busy">确认移除所选需求</button><button class="text-button" @click="decide(c,'reject')" :disabled="busy">保留原内容</button></div></article></section><details class="card detail"><summary>已处理记录</summary><p v-for="c in s.changes.filter((c:any)=>c.status!=='pending')" :key="c.id">{{kind(c.kind)}} · {{c.proposed?.text??'移除原需求'}} · {{status(c.status)}}</p></details><details class="card detail"><summary>需求与用例历史</summary><article v-for="(h,i) in [...s.history].reverse()" :key="String(i)"><p>{{h.value.code}} · 修订 {{h.revision}} · {{date(h.at)}}</p><pre>{{h.kind==='requirement'?h.value.text:JSON.stringify(h.value,null,2)}}</pre></article><p v-if="!s.history.length" class="muted">修改后将在这里保留历史。</p></details></template>
<details v-if="tasks.length" class="card detail"><summary>处理记录</summary><div class="task-record" v-for="t in tasks" :key="t.id">{{date(t.created_at)}} · {{({extract:'整理需求',generate:'生成用例',index:'整理资料索引'} as Record<string,string>)[t.kind]}} · {{status(t.status)}} <span class="error-text">{{t.error}}</span><button v-if="['failed','blocked'].includes(t.status)" class="text-button" @click="resumeTask(t)" :disabled="busy||!!active">继续已保存任务</button><details v-if="t.result?.partial"><summary>查看已整理部分</summary><pre>{{JSON.stringify(t.result.extracted,null,2)}}</pre></details></div><details v-if="trace.length"><summary>查看本次资料查阅过程</summary><pre>{{JSON.stringify(trace,null,2)}}</pre></details></details></template>
<footer>CaseFlow<span>从需求整理到用例交付</span></footer></div></main>
<div v-if="source" class="overlay source-overlay" @click.self="source=null"><section class="dialog" role="dialog" aria-modal="true" :aria-label="source.title"><div class="heading"><h2>{{source.title}}</h2><button class="close" @click="source=null" aria-label="关闭原文">×</button></div><pre>{{source.text}}</pre></section></div>
<div v-if="editor" class="overlay" @click.self="editor=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="编辑用例"><div class="heading"><h2>{{editor.code}} · 用例详情</h2><button class="close" @click="editor=null" aria-label="关闭用例">×</button></div><label>标题<input v-model="editor.title"></label><label>前置条件<textarea v-model="editor.preconditions" rows="2"></textarea></label><label>输入数据<textarea v-model="editor.data" rows="2"></textarea></label><label>操作步骤（每行一步）<textarea v-model="steps" rows="4"></textarea></label><label>预期结果<textarea v-model="editor.expected" rows="3"></textarea></label><p class="message" v-if="editor.basis==='suggestion'">这是补充建议，请核实预期结果再审核。</p><div class="citations"><button v-for="(q,i) in editor.citations" :key="String(i)" @click="citation(q)">查看依据：{{q.quote.slice(0,45)}}…</button></div><label>审核说明<input v-model="review" placeholder="说明核对了哪些规则和预期结果"></label><div class="actions"><button v-if="editor.replaces_case_id" class="primary" @click="applyProposal" :disabled="busy">应用到原用例</button><button v-else class="primary" @click="saveCase('approved')" :disabled="busy">保存并审核通过</button><button class="secondary" @click="saveCase('draft')" :disabled="busy">保存草稿</button><button class="text-button" @click="saveCase('rejected')" :disabled="busy">驳回</button></div></section></div>
<div v-if="settingsVisible" class="overlay" @click.self="settingsVisible=false"><section class="dialog" role="dialog" aria-modal="true" aria-label="设置"><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success">{{notice}}</p><div class="heading"><h2>模型设置</h2><button class="close" @click="settingsVisible=false" aria-label="关闭设置">×</button></div><template v-if="settings"><p class="message">{{settingsInfo?.reason}}</p><label>连接方式<select v-model="settings.mode"><option value="free">百炼免费模型</option><option value="compatible">兼容模型服务</option></select></label><label>模型名称<input v-model="settings.model"></label><label class="check"><input type="checkbox" v-model="settings.enabled">启用此模型处理已授权资料</label><details class="detail"><summary>连接与请求限制</summary><label>服务地址<input v-model="settings.base_url"></label><label>密钥环境变量名<input v-model="settings.key_env"></label><p class="muted">密钥在服务端配置，不在页面填写。免费模型需有效额度核验。</p><label>每日请求上限<input type="number" v-model.number="settings.daily_limit" min="1" max="200"></label><label>单次输出上限<input type="number" v-model.number="settings.max_output" min="256" max="2048"></label><p class="muted">今日已预留 {{settingsInfo?.used_today}} 次请求；次数不是金额上限。</p></details><button class="primary" @click="saveSettings" :disabled="busy">保存设置</button></template></section></div>
</div>
</template>
<style>
body{margin:0}.cf{font:14px/1.65 "Segoe UI","Microsoft YaHei",sans-serif;color:#253832;background:#f5f7f6;min-height:100vh}.cf *{box-sizing:border-box}.cf button,.cf input,.cf textarea,.cf select{font:inherit}.cf button{cursor:pointer}.cf button:disabled{opacity:.5;cursor:not-allowed}.cf aside{position:fixed;inset:0 auto 0 0;width:236px;background:#112e29;color:#eaf4ef;padding:28px 22px;display:flex;flex-direction:column}.cf .brand{display:flex;gap:12px;align-items:center;background:none;border:0;color:white;font-size:24px;font-weight:650;padding:0;text-align:left}.cf .brand b{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:#bddbc9;color:#183e31;font-size:25px}.cf .brand small{display:block;font-size:11px;color:#9cbbb0;font-weight:400;margin-top:3px}.cf .home{margin:38px 0 16px;background:none;border:0;color:#c4dbd0;text-align:left;padding:12px 10px}.cf .project-name{font-size:12px;color:#8fae9e;border-top:1px solid #315044;padding-top:22px;overflow-wrap:anywhere}.cf nav{display:grid;gap:7px;margin-top:10px}.cf nav button{display:flex;justify-content:space-between;border:0;background:none;color:#b5cec1;text-align:left;padding:12px 16px;border-radius:7px}.cf nav button.active{background:#294b3e;color:white}.cf nav small{background:#496753;border-radius:10px;padding:0 6px}.cf .aside-bottom{margin-top:auto;display:grid;gap:16px;color:#8fae9e;font-size:11px}.cf .aside-bottom button{color:#c4dbd0;background:none;border:0;text-align:left;padding:8px 10px}.cf main{margin-left:236px;min-width:0}.cf header{height:72px;background:white;border-bottom:1px solid #e0e7e2;padding:0 42px;display:flex;align-items:center;justify-content:space-between;color:#52685d;font-size:13px}.cf .local{color:#5b8270;background:#edf5ee;padding:5px 10px;border-radius:5px}.cf .content{max-width:1280px;padding:36px 42px;margin:auto}.cf .title{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}.cf h1{font-size:28px;letter-spacing:-.6px;margin:4px 0 8px;font-weight:650;line-height:1.4}.cf .title p{color:#7c8a81;margin:0}.cf .eyebrow{font-size:10px;letter-spacing:2px;color:#5a8d71;font-weight:650}.cf h2{font-size:16px;margin:0}.cf .card{background:#fff;border:1px solid #e0e7e2;border-radius:12px;padding:25px;margin-bottom:22px;min-width:0}.cf .card p{overflow-wrap:anywhere}.cf .heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:17px}.cf .heading>small{color:#8b998f;font-size:12px}.cf .create{display:flex;align-items:center;justify-content:space-between;gap:25px}.cf .create p{font-size:12px;margin:5px 0}.cf .inline{display:flex;align-items:flex-end;gap:14px}.cf .inline>input{min-width:260px}.cf .wrap{flex-wrap:wrap}.cf .wrap>label{flex:1;min-width:160px}.cf label{display:block;margin:16px 0 8px;font-size:13px;color:#5b6c62}.cf input:not([type=checkbox]):not([type=file]),.cf select,.cf textarea{display:block;width:100%;padding:10px 12px;border:1px solid #dce5de;border-radius:7px;background:#fcfdfc;color:#293f33;margin-top:5px;line-height:1.6}.cf textarea{resize:vertical}.cf input[type=checkbox]{width:16px;height:16px;accent-color:#28634d;flex-shrink:0;margin:4px 0 0}.cf :focus-visible{outline:3px solid #a9cbb8;outline-offset:2px}.cf .primary,.cf .secondary{display:inline-flex;align-items:center;justify-content:center;padding:10px 16px;border-radius:7px;white-space:nowrap;font-weight:500;font-size:13px;line-height:1.6;text-decoration:none;margin:0}.cf .primary{background:#245d46;color:white;border:1px solid #245d46}.cf .primary:hover{background:#194a36}.cf .secondary{background:white;color:#51685a;border:1px solid #dbe5dd}.cf .upload{cursor:pointer}.cf .upload input{display:none}.cf .actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:16px}.cf .text-button{border:0;background:none;color:#39795b;padding:6px 0;font-size:13px}.cf .muted{font-size:12px;color:#8a998f}.cf .empty{padding:30px 15px;text-align:center;color:#8a998f;font-size:13px}.cf .project-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:24px}.cf .project{position:relative;text-align:left;margin:0;color:#253832}.cf .project:hover{border-color:#83ac92;box-shadow:0 5px 18px #183d2510}.cf .project h3{font-size:17px;margin:17px 0 8px}.cf .project p{font-size:12px;color:#718779}.cf .project small{font-size:11px;color:#95a298}.cf .folder{font-size:24px;color:#5a896b}.cf .arrow{position:absolute;right:20px;top:22px;color:#86a38f}.cf .examples{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.cf .examples button{border:1px dashed #cddbd0;border-radius:10px;text-align:left;padding:18px 20px;background:#f9fbf9;color:#45654f;font-weight:600}.cf .examples small{display:block;color:#91a194;font-weight:400;margin-top:6px}.cf .document{display:flex;justify-content:space-between;gap:15px;align-items:center;border-top:1px solid #edf1ed;padding:12px 0}.cf .check{display:flex;align-items:flex-start;gap:10px;margin:0}.cf .check small{display:block;color:#93a096;font-size:11px;margin-top:3px}.cf .consent{background:#f1f7f1;border-radius:8px;padding:12px;margin-top:16px;font-size:12px}.cf .requirement{padding:22px 0;border-top:1px solid #e7ede7}.cf .item-title{display:flex;gap:12px;align-items:center;margin-bottom:12px}.cf .badge{display:inline-block;background:#eef2ee;color:#7a897b;font-size:11px;border-radius:5px;padding:3px 8px;white-space:nowrap}.cf .badge.confirmed,.cf .badge.approved{color:#36714b;background:#eaf4eb}.cf .badge.needs_review,.cf .badge.draft{color:#9a7938;background:#fbf3e2}.cf .badge.rejected,.cf .badge.excluded{color:#a07770;background:#f7eeeb}.cf .questions{background:#fffaf0;padding:14px;border-radius:8px;font-size:13px;color:#92773c;margin-top:14px}.cf .questions p{margin:5px 0}.cf .citations{display:flex;flex-wrap:wrap;gap:12px;margin:10px 0}.cf .citations button{background:none;border:0;padding:0;color:#508567;font-size:12px;text-align:left}.cf .bottom{border-top:1px solid #e7e